.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 16px;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #fff;
    border-bottom: 1px solid #202225;
    margin: 0;
}

.channel-list {
    list-style: none;
    padding: 8px 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
    border-radius: 4px;
    margin: 2px 8px;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #404348;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.message-area {
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    transition: width 0.2s;
}

.message-area.full-width {
    width: 80%;
}

.message-area.with-thread {
    width: 55%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #2f3136;
}

.message-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
