namespace sv_245bf5988d684c5891ec6249b227f0f9.Services;

/// <summary>
/// Stub implementation of IChatService for development/demo purposes.
/// Replace with a real implementation backed by a database or API.
/// </summary>
public class StubChatService : IChatService
{
    private readonly List<Channel> _channels = new()
    {
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering updates and discussions", 0),
        new(3, "design", "Design reviews and feedback", 1),
        new(4, "random", "Off-topic conversations", 5),
    };

    private readonly List<Message> _messages = new()
    {
        new(1, 1, "Alice", "Hey team! How's everyone doing today?", DateTime.UtcNow.AddHours(-2), null, new() { new("👍", new() { "Bob", "Charlie" }) }),
        new(2, 1, "Bob", "Doing great! Just finished the new feature.", DateTime.UtcNow.AddHours(-1.5), null, new() { new("🎉", new() { "Alice", "Diana" }), new("❤️", new() { "Charlie" }) }),
        new(3, 1, "Charlie", "Nice work Bob! Can you share a demo?", DateTime.UtcNow.AddMinutes(-45), 2, new()),
        new(4, 1, "Diana", "I'd love to see it too!", DateTime.UtcNow.AddMinutes(-30), 2, new()),
        new(5, 1, "Alice", "Let's schedule a demo session for tomorrow.", DateTime.UtcNow.AddMinutes(-10), null, new() { new("👍", new() { "Bob", "Charlie", "Diana" }) }),
        new(6, 2, "Bob", "Deployed v2.1 to staging. Please test.", DateTime.UtcNow.AddHours(-3), null, new()),
        new(7, 2, "Charlie", "On it! Will report back.", DateTime.UtcNow.AddHours(-2.5), 6, new()),
    };

    public Task<List<Channel>> GetChannelsAsync() => Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        var result = _messages
            .Where(m => m.ChannelId == channelId)
            .OrderBy(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .ToList();
        return Task.FromResult(result);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var id = _messages.Count > 0 ? _messages.Max(m => m.Id) + 1 : 1;
        var message = new Message(id, channelId, "You", content, DateTime.UtcNow, replyToId, new());
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var replies = _messages.Where(m => m.ReplyToId == rootMessageId).OrderBy(m => m.SentAt).ToList();
        return Task.FromResult(replies);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new() { "You" }));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

